from math import comb

def calculate_ratio(n):
    # f(K_n) is the number of triangles (K3) = C(n, 3)
    f_kn = comb(n, 3)

    # g(K_n) is the number of tetrahedra (K4) = C(n, 4)
    g_kn = comb(n, 4)

    if f_kn == 0:
        return "Undefined (f_kn = 0)"

    ratio = (g_kn**3) / (f_kn**4)
    return ratio

results = {}
for n in range(4, 11):
    results[n] = calculate_ratio(n)

print("n | C(n, 3) [f(Kn)] | C(n, 4) [g(Kn)] | Ratio g(Kn)^3 / f(Kn)^4")
print("-" * 60)
for n in range(4, 11):
    ratio = results[n]
    f_kn = comb(n, 3)
    g_kn = comb(n, 4)

    if isinstance(ratio, float):
        print(f"{n:2} | {f_kn:15} | {g_kn:15} | {ratio}")
    else:
        print(f"{n:2} | {f_kn:15} | {g_kn:15} | {ratio}")

from math import comb

def R(n):
    if n < 4:
        return 0
    f_kn = comb(n, 3)
    g_kn = comb(n, 4)
    return (g_kn**3) / (f_kn**4)

# Check values up to n=10
print("n | R(n)")
for n in range(4, 11):
    r_n = R(n)
    print(f"{n} | {r_n}")

